tool_input.command:
cat >> src/openingHours.test.ts <<'EOF'

function errorOf(text: string): { code: string; column: number } {
  try {
    parseOpeningHours(text);
  } catch (e) {
    if (e instanceof OpeningHoursError) return { code: e.code, column: e.column };
    throw e;
  }
  throw new Error(`expected "${text}" to fail`);
}

test("empty text is rejected", () => {
  expect(errorOf("")).toEqual({ code: "EMPTY", column: 1 });
  expect(errorOf("   ")).toEqual({ code: "EMPTY", column: 1 });
});
EOF
sed -i 's/import { OpeningHoursError } from/import { OpeningHoursError, parseOpeningHours } from/' src/openingHours.test.ts
bun test 2>&1 | tail -5
